/// The words for `component`'s prop `prop`, when it has a row.
pub fn of(component: &str, prop: &str) -> Option<&'static PropDoc> {
    DOCS.iter().find(|d| d.component == component && d.prop == prop)
}


#[cfg(test)]
mod tests {
    #[test]
    fn every_prop_of_every_built_in_has_its_words() {
        let mut missing = Vec::new();
        for sig in crate::registry::COMPONENTS {
            let q = sig.qualified();
            for prop in sig.positional.iter().chain(sig.props.iter()) {
                if super::of(&q, prop.name).is_none() {
                    missing.push(format!("{q}.{}", prop.name));
                }
            }
        }
        assert!(missing.is_empty(), "these props say nothing in prop_docs.rs: {missing:?}");
        let known: std::collections::HashSet<(String, &str)> = crate::registry::COMPONENTS
            .iter()
            .flat_map(|s| {
                let q = s.qualified();
                s.positional
                    .iter()
                    .chain(s.props.iter())
                    .map(move |p| (q.clone(), p.name))
            })
            .collect();
        let stale: Vec<String> = super::DOCS
            .iter()
            .filter(|d| !known.contains(&(d.component.to_string(), d.prop)))
            .map(|d| format!("{}.{}", d.component, d.prop))
            .collect();
        assert!(stale.is_empty(), "prop_docs.rs has rows for props that are gone: {stale:?}");
    }
}
